	SET_BIT(RCC_CFGR, 16);            /* PLLSRC = HSE */
	RCC_CFGR &= ~(0xFU << 18);
	RCC_CFGR |=  (0x7U << 18);        /* PLLMUL = x9 (0b0111) */
	RCC_CFGR &= ~(0x7U << 8);
	RCC_CFGR |=  (0x4U << 8);         /* PPRE1 = chia 2 (0b100) */

	/* 6. Bật PLL và đợi khóa tần số */
	SET_BIT(RCC_CR, 24);
	while (!(RCC_CR & (1U << 25))) {
	}

	/* 7. Chuyển SYSCLK sang PLL và đợi xác nhận */
	RCC_CFGR &= ~(0x3U << 0);
	RCC_CFGR |=  (0x2U << 0);
	while (((RCC_CFGR >> 2) & 0x3U) != 0x2U) {
	}

	/* Cấu hình USART1 (TX = PA9, Baudrate = 115200 @ 72 MHz APB2) */
	SET_BIT(RCC_APB2ENR, 14);         /* Bit 14 (USART1EN): Bật clock USART1 */
	GPIOA_CRH &= ~(0xFU << 4);        /* Xóa 4 bit cấu hình cũ của PA9 (bit 7:4) */
	GPIOA_CRH |=  (0xBU << 4);        /* 0xB (0b1011) -> AF Push-Pull 50 MHz */
	USART1_BRR = 72000000U / 115200U; /* 625 = 0x271 (Mantissa = 39, Fraction = 1) */
	SET_BIT(USART1_CR1, 3);           /* Bit 3 (TE): Bật bộ phát Transmitter */
	SET_BIT(USART1_CR1, 13);          /* Bit 13 (UE): Bật ngoại vi USART1 */

	/* 8. Cấu hình SysTick tạo cờ mỗi 1 ms tại 72 MHz */
	SYST_RVR = 72000 - 1;
	SYST_CVR = 0;
	SYST_CSR = 0x5;

	/* 9. Chọn nguồn xuất ra MCO (PA8) */
	RCC_CFGR &= ~(0x7U << 24);
	RCC_CFGR |=  (0x6U << 24);

	/* 10. Nối PA0 với đường ngắt EXTI0 */
	SET_BIT(RCC_APB2ENR, 0);          /* Bật clock AFIO (bit 0) */
	AFIO_EXTICR1 &= ~(0xFU << 0);     /* Chọn cổng A (0000) cho EXTI0 */
	SET_BIT(EXTI_FTSR, 0);            /* Kích hoạt ở cạnh xuống */
	SET_BIT(EXTI_IMR, 0);             /* Cho phép ngắt đường 0 */
	SET_BIT(NVIC_ISER0, 6);           /* Bật ngắt EXTI0 (IRQ số 6) */

	/* 11. Khởi tạo TIM2 tạo ngắt tràn mỗi 1 ms (xung Timer APB1 = 72 MHz) */
	SET_BIT(RCC_APB1ENR, 0);          /* Bit 0 (TIM2EN): Bật clock cho TIM2 */
	TIM2_PSC = 72 - 1;                /* Chia 72 -> 1 MHz (1 tick = 1 us) */
	TIM2_ARR = 1000 - 1;              /* Đếm 1000 tick -> 1000 us = 1 ms */
	SET_BIT(TIM2_DIER, 0);            /* Bit 0 (UIE): Cho phép ngắt Update Interrupt */
	SET_BIT(TIM2_CR1, 0);             /* Bit 0 (CEN): Bắt đầu cho TIM2 đếm */
	SET_BIT(NVIC_ISER0, 28);          /* Bật ngắt TIM2 (IRQ số 28) */

